/**
 * Returns the minimum-necessary summary (SECURITY_MODEL §8 rule 4) for up to 50 patient IDs in one call (new inventory row #241; D54). A read, not a search: no criteria, IDs only in the body. Each ID returned is audited as a chart access. Restricted patients come back with summary fields only and `restricted: true`.
 * @summary Get patient summaries by ID
 */
export const getPatientSummaries = async (patientSummariesRequest: PatientSummariesRequest, options?: Parameters<typeof apiFetch>[1]): Promise<getPatientSummariesResponse> => {

    const getHeaders = (h?: NonNullable<RequestInit['headers']>): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(h as Iterable<Iterable<string>>, (entry) => Array.from(entry) as [string, string]),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
return apiFetch<getPatientSummariesResponse>(getGetPatientSummariesUrl(),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...getHeaders(options?.headers) },
    body: JSON.stringify(patientSummariesRequest)
  }
);}


